namespace PriorityTaskManager.Models
{
    /// <summary>
    /// Stores the editable task fields for one recurring occurrence, keyed by its original recurrence date.
    /// </summary>
    public sealed class TaskOccurrenceOverride
    {
        /// <summary>Gets or sets the original date generated by the recurrence rule.</summary>
        public DateTime OriginalOccurrenceDate { get; set; }

        /// <summary>Gets or sets the overridden title.</summary>
        public string Title { get; set; } = string.Empty;

        /// <summary>Gets or sets the overridden description.</summary>
        public string Description { get; set; } = string.Empty;

        /// <summary>Gets or sets the overridden due date.</summary>
        public DateTime? DueDate { get; set; }

        /// <summary>Gets or sets the overridden earliest start date.</summary>
        public DateTime? NotBefore { get; set; }

        /// <summary>Gets or sets the overridden estimated duration.</summary>
        public TimeSpan EstimatedDuration { get; set; }

        /// <summary>Gets or sets the overridden importance.</summary>
        public int Importance { get; set; }

        /// <summary>Gets or sets the overridden complexity.</summary>
        public int Complexity { get; set; }

        /// <summary>Gets or sets whether the occurrence is pinned.</summary>
        public bool IsPinned { get; set; }

        /// <summary>Gets or sets whether the occurrence can be split across sessions.</summary>
        public bool IsDivisible { get; set; }

        /// <summary>Gets or sets the overridden associated link.</summary>
        public string? Link { get; set; }

        /// <summary>Creates a deep copy of this override.</summary>
        public TaskOccurrenceOverride Clone() => new()
        {
            OriginalOccurrenceDate = OriginalOccurrenceDate,
            Title = Title,
            Description = Description,
            DueDate = DueDate,
            NotBefore = NotBefore,
            EstimatedDuration = EstimatedDuration,
            Importance = Importance,
            Complexity = Complexity,
            IsPinned = IsPinned,
            IsDivisible = IsDivisible,
            Link = Link
        };

        /// <summary>Applies the override to a projected occurrence task.</summary>
        public void ApplyTo(TaskItem task)
        {
            task.Title = Title;
            task.Description = Description;
            task.DueDate = DueDate;
            task.NotBefore = NotBefore;
            task.EstimatedDuration = EstimatedDuration;
            task.Importance = Importance;
            task.Complexity = Complexity;
            task.IsPinned = IsPinned;
            task.IsDivisible = IsDivisible;
            task.Link = Link;
        }
    }
}
